#include "data_source_status_model.hpp"
#include <QJsonDocument>
#include <QCryptographicHash>
#include <QDateTime>
#include <QRegularExpression>
#include <QUrl>
#include <QSet>
#include <cmath>
#include <stdexcept>
namespace dataSourceStatus {
QString stateName(const QString& value){return QMap<QString,QString>{{"available","本机记录可用"},{"partial","部分记录"},{"unavailable","本轮未取得"},{"unknown","未知"},{"fresh","本机标记新取得"},{"cached","保留缓存"},{"stale","旧缓存"},{"none","无"},{"saved","已保存"},{"pending","待保存"},{"failed","保存失败"},{"observed-once","仅本次观测"},{"declared","来源声明"},{"unsupported","未接入"},{"public-snapshot","公开快照"},{"vendor-classified","提供方分类口径"},{"local-estimate","本机估算"},{"local-sample","本机采样"},{"imported-unverified","导入未验证"},{"snapshot","快照"},{"day","日"},{"week","周"},{"month","月"},{"year","年"},{"qfq","前复权"},{"hfq","后复权"}}.value(value,value);}
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
static bool sensitive(QString s){return QRegularExpression("(?i)(sk-|bearer|api[_-]?key|password|authorization|token[=:]|https?://|[a-z]:[\\\\/])").match(s).hasMatch();}
static QString text(const QJsonObject& o,const char* k,int max=1000){auto v=o.value(k);require(v.isUndefined()||v.isNull()||v.isString(),"文本字段类型无效");QString s=v.toString();require(s.size()<=max,"文本字段超过范围");return sensitive(s)?QString("[敏感详情已排除]"):s;}
static QString id(const QJsonObject& o,const char* k,int max=80){QString s=text(o,k,max);require(QRegularExpression("^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$").match(s).hasMatch()&&!sensitive(s),"身份或来源标识无效");return s;}
static QString state(const QJsonObject& o,const char* k,const QStringList& options){auto v=o.value(k);require(v.isUndefined()||v.isString(),"状态字段无效");return options.contains(v.toString())?v.toString():QString("unknown");}
static QJsonValue time(const QJsonObject& o,const char* k){auto v=o.value(k);if(v.isNull()||v.isUndefined()||v=="")return QJsonValue::Null;QString s=v.toString();require(v.isString()&&s.size()<=40&&QRegularExpression("(Z|[+-][0-9]{2}:[0-9]{2})$").match(s).hasMatch()&&QDateTime::fromString(s,Qt::ISODateWithMs).isValid(),"时间字段无效");return s;}
QJsonObject empty(){return {{"schema","native-data-source-status/v1"},{"generatedAt",QJsonValue::Null},{"inventoryScope","host-injected-only"},{"completeInventory",false},{"records",QJsonArray{}}};}
QJsonObject snapshot(const QJsonObject& input){require(input.value("schema")=="native-data-source-status/v1"&&input.value("records").isArray(),"不是本机数据源状态格式");auto records=input.value("records").toArray();require(records.size()<=1000,"来源记录超过1000条");QJsonArray safe;QSet<QString> seen;
 for(auto v:records){require(v.isObject(),"来源记录无效");auto o=v.toObject();QString provider=id(o,"provider"),product=state(o,"product",{"quote","intraday","kline","auction","funds","industry","concept","news","indices","breadth","level2"}),grain=id(o,"granularity",40);require(product!="unknown"&&o.value("target").isObject(),"产品或精确目标缺失");auto t=o.value("target").toObject();QString kind=state(t,"kind",{"instrument","board","market","news","scope"});QJsonObject target{{"kind",kind}};require(kind!="unknown","目标种类无效");
 if(kind=="board"){target["provider"]=id(t,"provider");target["taxonomy"]=state(t,"taxonomy",{"industry","concept"});target["code"]=id(t,"code");require(target["taxonomy"]!="unknown","板块来源或分类不匹配");}
 else{QString targetId=id(t,"id",160);if(kind=="instrument")require(QRegularExpression("^(SH|SZ|BJ|HK|US):(stock|etf|index|fund):[A-Za-z0-9._-]{1,16}$").match(targetId).hasMatch(),"证券须使用完整市场/类型/代码身份");target["id"]=targetId;}
 QJsonObject r{{"provider",provider},{"product",product},{"granularity",grain},{"target",target},{"route",text(o,"route",60)},{"acquisition",state(o,"acquisition",{"available","partial","unavailable","unknown"})},{"cache",state(o,"cache",{"fresh","cached","stale","none","unknown"})},{"persistence",state(o,"persistence",{"saved","pending","failed","unknown"})},{"evidenceKind",state(o,"evidenceKind",{"public-snapshot","vendor-classified","local-estimate","local-sample","imported-unverified","unknown"})},{"authorization","unknown"},{"sustainedRealtime","unknown"},{"capability",state(o,"capability",{"observed-once","declared","unsupported","unknown"})},{"error",text(o,"error")},{"note",text(o,"note")},{"sourceTiming",text(o,"sourceTiming",500)},{"sampleScope",text(o,"sampleScope",500)},{"coverageScope",text(o,"coverageScope",100)},{"adjustment",state(o,"adjustment",{"qfq","hfq","none","unknown"})}};
 for(auto k:{"sourceTime","fetchedAt","persistedAt","attemptedAt","startedAt"})r[k]=time(o,k);
 QString date=text(o,"dataDate",10);require(date.isEmpty()||(QRegularExpression("^[0-9]{4}-[0-9]{2}-[0-9]{2}$").match(date).hasMatch()&&QDate::fromString(date,Qt::ISODate).isValid()),"数据日期无效");r["dataDate"]=date.isEmpty()?QJsonValue(QJsonValue::Null):QJsonValue(date);
 for(auto k:{"rowCount","declaredTotal","elapsedMs","pageCount"}){auto n=o.value(k);require(n.isUndefined()||n.isNull()||(n.isDouble()&&std::isfinite(n.toDouble())&&n.toDouble()>=0&&n.toDouble()<=9007199254740991.&&std::floor(n.toDouble())==n.toDouble()),"计数字段无效");r[k]=n.isDouble()?n:QJsonValue(QJsonValue::Null);}
 auto complete=o.value("coverageComplete");require(complete.isUndefined()||complete.isNull()||complete.isBool(),"覆盖字段无效");r["coverageComplete"]=complete.isBool()?complete:QJsonValue(QJsonValue::Null);
 QString link=o.value("sourceUrl").toString();QUrl url(link,QUrl::StrictMode);QString sourceUrl;if(link.size()<=512&&!link.contains('%')&&url.isValid()&&url.scheme()=="https"&&!url.host().isEmpty()&&url.userInfo().isEmpty()&&!url.hasQuery()&&!url.hasFragment()&&!QRegularExpression("(?i)(sk-|bearer|api[_-]?key|password|token)").match(link).hasMatch())sourceUrl=url.toString(QUrl::FullyEncoded);r["sourceUrl"]=sourceUrl.isEmpty()?QJsonValue(QJsonValue::Null):QJsonValue(sourceUrl);
 if(r["capability"]=="observed-once"&&(r["fetchedAt"].isNull()||(r["acquisition"]!="available"&&r["acquisition"]!="partial")))r["capability"]="unknown";
 QString targetKey=kind+"|"+(kind=="board"?target.value("provider").toString()+"|"+target.value("taxonomy").toString()+"|"+target.value("code").toString():target.value("id").toString());QString key=QString::fromLatin1(QCryptographicHash::hash((provider+"|"+product+"|"+grain+"|"+targetKey).toUtf8(),QCryptographicHash::Sha256).toHex());require(!seen.contains(key),"完整来源/产品/粒度/目标身份重复");seen.insert(key);r["key"]=key;safe.append(r);
 }auto result=empty();result["generatedAt"]=time(input,"generatedAt");result["records"]=safe;require(QJsonDocument(result).toJson(QJsonDocument::Compact).size()<=1024*1024,"来源证据超过1MiB");return result;
}
QJsonArray rows(const QJsonObject& s,const QJsonObject& filters){QJsonArray out;QString search=filters.value("search").toString().trimmed();for(auto v:s.value("records").toArray()){auto r=v.toObject();bool match=true;for(auto k:{"provider","product","granularity","acquisition"}){QString f=filters.value(k).toString();if(!f.isEmpty()&&f!="*"&&r.value(k)!=f)match=false;}if(match&&(search.isEmpty()||title(r).contains(search,Qt::CaseInsensitive)))out.append(r);}return out;}
bool canOpen(const QJsonObject& r,const QStringList& allow){QString route=r.value("route").toString(),p=r.value("product").toString(),kind=r.value("target").toObject().value("kind").toString();if(!allow.contains(route))return false;if(route=="detail"||route=="stock")return kind=="instrument"&&QStringList{"quote","intraday","kline"}.contains(p);if(route=="auction")return kind=="instrument"&&p=="auction";if(route=="capital"||route=="funds")return p=="funds"&&(kind=="instrument"||kind=="market"||kind=="scope");if(route=="sector-watch"||route=="sectors"||route=="industry-discovery")return (p=="industry"||p=="concept")&&(kind=="board"||kind=="market"||kind=="scope");if(route=="news")return p=="news";if(route=="market"||route=="market-overview")return QStringList{"indices","breadth","industry","concept"}.contains(p)&&(kind=="market"||kind=="scope");return false;}
QJsonObject navigation(const QJsonObject& r){auto t=r.value("target").toObject();t["sourceProvider"]=r.value("provider");t["product"]=r.value("product");t["granularity"]=r.value("granularity");t["adjustment"]=r.value("adjustment");t["evidenceKey"]=r.value("key");return t;}
QString productName(const QString& p){return QMap<QString,QString>{{"quote","报价"},{"intraday","分时"},{"kline","K线"},{"auction","竞价"},{"funds","资金"},{"industry","行业"},{"concept","概念"},{"news","资讯"},{"indices","指数"},{"breadth","市场宽度"},{"level2","Level-2"}}.value(p,p);}
QString title(const QJsonObject& r){auto t=r.value("target").toObject();QString target=t.value("kind")=="board"?t.value("provider").toString()+" / "+t.value("taxonomy").toString()+" / "+t.value("code").toString():t.value("id").toString();return r.value("provider").toString()+" · "+productName(r.value("product").toString())+" · "+stateName(r.value("granularity").toString())+" · "+target;}
QString description(const QJsonObject& r){auto label=[](QJsonValue v){return v.isNull()?QString("未知"):v.isBool()?(v.toBool()?QString("是"):QString("否")):v.isDouble()?QString::number(v.toDouble(),'g',15):stateName(v.toString());};QString text=title(r)+"\n";for(auto pair:{qMakePair("acquisition","取得状态"),qMakePair("cache","缓存状态"),qMakePair("persistence","本机保存"),qMakePair("sourceTime","来源时间"),qMakePair("dataDate","数据日期"),qMakePair("fetchedAt","取得时间"),qMakePair("persistedAt","保存时间"),qMakePair("attemptedAt","最近尝试"),qMakePair("evidenceKind","证据口径"),qMakePair("capability","能力证据"),qMakePair("rowCount","记录数"),qMakePair("coverageComplete","当前范围覆盖完整")})text+=QString::fromUtf8(pair.second)+"："+label(r.value(pair.first))+"\n";return text+"L2 授权：未知；稳定实时能力：未知\n"+r.value("error").toString()+"\n"+r.value("note").toString();}
QByteArray exportEvidence(const QJsonObject& s,const QJsonObject& filters){auto safe=snapshot(s);safe["records"]=rows(safe,filters);safe["exportedAt"]=QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);return QJsonDocument(safe).toJson(QJsonDocument::Indented);}
}
